input:
{
  "title": "Amazon Middle East — Keyword Rank",
  "type": "object",
  "schemaVersion": 1,
  "properties": {
    "keywords": {
      "title": "Keywords",
      "type": "array",
      "editor": "stringList",
      "description": "Search keywords to rank. Duplicates are ignored.",
      "prefill": [
        "shampoo"
      ]
    },
    "locale": {
      "title": "Storefront",
      "type": "string",
      "enum": [
        "ae",
        "sa",
        "eg"
      ],
      "enumTitles": [
        "UAE (amazon.ae)",
        "Saudi Arabia (amazon.sa)",
        "Egypt (amazon.eg)"
      ],
      "default": "ae",
      "description": "Which Amazon storefront.",
      "editor": "select"
    },
    "pages": {
      "title": "Pages per keyword",
      "type": "integer",
      "description": "Result pages to capture per keyword. Leave at 0 to capture every result page; the run stops as soon as the results end.",
      "default": 0,
      "minimum": 0,
      "maximum": 7,
      "editor": "number",
      "prefill": 0
    },
    "delayMs": {
      "title": "Delay between calls (ms)",
      "type": "integer",
      "description": "Pause between page fetches.",
      "default": 1500,
      "minimum": 500,
      "editor": "number"
    },
    "callsPerSession": {
      "title": "Calls per session",
      "type": "integer",
      "description": "Re-mint the session after this many page fetches.",
      "default": 80,
      "minimum": 5,
      "editor": "number"
    },
    "proxyConfiguration": {
      "title": "Proxy",
      "type": "object",
      "editor": "proxy",
      "description": "On the Apify platform this decides egress. Residential proxy in the storefront's country is recommended (AE for the default locale). On our own servers it is ignored and our residential proxy is used.",
      "default": {
        "useApifyProxy": true,
        "apifyProxyGroups": [
          "RESIDENTIAL"
        ],
        "apifyProxyCountry": "AE"
      }
    }
  },
  "required": [
    "keywords"
  ]
}
